 16	/// <summary>
 17	/// Base class for renderer components called render pass.
 18	/// Each render pass supports proper resources initialization and disposing.
 19	/// </summary>
 20	/// <seealso cref="Object" />
 21	class FLAXENGINE_API RendererPassBase : public Object
 22	{
 23	protected:
 24	#if !GPU_ENABLE_PRELOADING_RESOURCES
 25	    bool _lazyInit = true;
 26	#endif
 27	    bool _hasValidResources;
 28	
 29	    /// <summary>
 30	    /// Init
 31	    /// </summary>
 32	    RendererPassBase()
 33	    {
 34	        _hasValidResources = false;
 35	    }
 36	
 37	public:
 38	
 39	    /// <summary>
 40	    /// Initialize service.
 41	    /// </summary>
 42	    virtual bool Init()
 43	    {
 44	        return false;
 45	    }
 46	
 47	    /// <summary>
 48	    /// Cleanup service data.
 49	    /// </summary>
 50	    virtual void Dispose()
 51	    {
 52	        // Clear flag
 53	        _hasValidResources = false;
 54	    }
 55	
 56	    /// <summary>
 57	    /// Determines whether can render this pass. Checks if pass is ready and has valid resources loaded.
 58	    /// </summary>
 59	    /// <returns><c>true</c> if can render pass; otherwise, <c>false</c>.</returns>
 60	    bool IsReady()
 61	    {
 62	        return !checkIfSkipPass();
 63	    }
 64	
 65	protected:
 66	
 67	    bool checkIfSkipPass()
 68	    {
 69	        if (_hasValidResources)
 70	            return false;
 71	#if !GPU_ENABLE_PRELOADING_RESOURCES
 72	        if (_lazyInit)
 73	        {
 74	            _lazyInit = false;
 75	            Init();
 76	        }
 77	#endif
 78	        const bool setupFailed = setupResources();
 79	        _hasValidResources = !setupFailed;
 80	        return setupFailed;
 81	    }
 82	
 83	    void invalidateResources()
 84	    {
 85	        // Clear flag
 86	        _hasValidResources = false;
 87	    }
 88	
 89	    virtual bool setupResources()
 90	    {
 91	        return false;
 92	    }
 93	};
