135	void RenderAntiAliasingPass(RenderContext& renderContext, GPUTexture* input, GPUTextureView* output, const Viewport& outputViewport)
136	{
137	    auto context = GPUDevice::Instance->GetMainContext();
138	    const auto aaMode = renderContext.List->Settings.AntiAliasing.Mode;
139	    if (ContrastAdaptiveSharpeningPass::Instance()->CanRender(renderContext))
140	    {
141	        if (aaMode == AntialiasingMode::FastApproximateAntialiasing ||
142	            aaMode == AntialiasingMode::SubpixelMorphologicalAntialiasing)
143	        {
144	            // AA -> CAS -> Output
145	            auto tmpImage = RenderTargetPool::Get(input->GetDescription());
146	            RENDER_TARGET_POOL_SET_NAME(tmpImage, "TmpImage");
147	            context->SetViewportAndScissors((float)tmpImage->Width(), (float)tmpImage->Height());
148	            if (aaMode == AntialiasingMode::FastApproximateAntialiasing)
149	                FXAA::Instance()->Render(renderContext, input, tmpImage->View());
150	            else
151	                SMAA::Instance()->Render(renderContext, input, tmpImage->View());
152	            context->ResetSR();
153	            context->ResetRenderTarget();
154	            context->SetViewportAndScissors(outputViewport);
155	            ContrastAdaptiveSharpeningPass::Instance()->Render(renderContext, tmpImage, output);
156	            RenderTargetPool::Release(tmpImage);
157	        }
158	        else
159	        {
160	            // CAS -> Output
161	            context->SetViewportAndScissors(outputViewport);
162	            ContrastAdaptiveSharpeningPass::Instance()->Render(renderContext, input, output);
163	        }
164	    }
165	    else
166	    {
167	        // AA -> Output
168	        context->SetViewportAndScissors(outputViewport);
169	        if (aaMode == AntialiasingMode::FastApproximateAntialiasing)
170	            FXAA::Instance()->Render(renderContext, input, output);
171	        else if (aaMode == AntialiasingMode::SubpixelMorphologicalAntialiasing)
172	            SMAA::Instance()->Render(renderContext, input, output);
173	        else
174	        {
175	            PROFILE_GPU("Copy frame");
176	            context->SetRenderTarget(output);
177	            context->Draw(input);
178	        }
179	    }
180	}
