 11	bool RenderGraphCompiler::Compile(RenderGraph* graph)
 12	{
 13	    if (!graph)
 14	        return false;
 15	
 16	    // Clear previous compilation data
 17	    Clear();
 18	
 19	    // Step 1: Cull unused passes
 20	    CullPasses(graph);
 21	
 22	    // Step 2: Determine execution order (topological sort)
 23	    if (!DetermineExecutionOrder(graph))
 24	    {
 25	        LOG(Error, "RenderGraph compilation failed: cyclic dependency detected");
 26	        return false;
 27	    }
 28	
 29	    // Step 3: Analyze resource lifetimes
 30	    AnalyzeResourceLifetimes(graph);
 31	
 32	    // Step 4: Optimize memory allocation
 33	    OptimizeMemoryAllocation(graph);
 34	
 35	    return true;
 36	}
