 66	void RenderGraphCompiler::MarkPassAsUsed(RenderGraph* graph, RenderGraphPass* pass, HashSet<int32>& usedPasses)
 67	{
 68	    if (!pass || pass->_passIndex < 0)
 69	        return;
 70	
 71	    // Already marked
 72	    if (usedPasses.Contains(pass->_passIndex))
 73	        return;
 74	
 75	    // Mark this pass as used
 76	    usedPasses.Add(pass->_passIndex);
 77	    pass->_culled = false;
