106	bool RenderGraphCompiler::TopologicalSortDFS(RenderGraph* graph, RenderGraphPass* pass, HashSet<int32>& visited, HashSet<int32>& recursionStack)
107	{
108	    if (!pass || pass->_culled)
109	        return true;
110	
111	    // Check for cycle
112	    if (recursionStack.Contains(pass->_passIndex))
113	    {
114	        LOG(Error, "RenderGraph cycle detected at pass: {0}", pass->GetName());
115	        return false;
116	    }
117	
118	    // Already visited
119	    if (visited.Contains(pass->_passIndex))
120	        return true;
121	
122	    // Mark as being processed
123	    recursionStack.Add(pass->_passIndex);
124	
125	    // Visit all dependencies (passes that write to resources this pass reads)
126	    // TODO: For each resource this pass reads:
127	    //   Find the pass that writes to it
128	    //   if (!TopologicalSortDFS(graph, writerPass, visited, recursionStack))
129	    //       return false;
130	
131	    // Mark as visited
132	    visited.Add(pass->_passIndex);
133	    recursionStack.Remove(pass->_passIndex);
134	
135	    // Add to sorted list
136	    _sortedPasses.Add(pass);
137	
138	    return true;
139	}
