 21	bool RenderGraphExecutor::Execute(RenderGraph* graph, RenderGraphCompiler* compiler, GPUContext* context)
 22	{
 23	    if (!graph || !compiler || !context)
 24	        return false;
 25	
 26	    PROFILE_CPU_NAMED("RenderGraph.Execute");
 27	
 28	    // Clear previous state
 29	    _textureStates.Clear();
 30	    _bufferStates.Clear();
 31	
 32	    // Get sorted passes from compiler
 33	    const auto& sortedPasses = compiler->GetSortedPasses();
 34	
 35	    // Execute passes in order
 36	    RenderGraphPass* previousPass = nullptr;
 37	    for (int32 i = 0; i < sortedPasses.Count(); i++)
 38	    {
 39	        RenderGraphPass* pass = sortedPasses[i];
 40	        
 41	        // Skip culled passes
 42	        if (pass->_culled)
 43	            continue;
 44	
 45	        // Insert synchronization if needed
 46	        if (previousPass)
 47	            InsertSynchronization(context, previousPass, pass);
 48	
 49	        // Transition resources to required states
 50	        TransitionResources(graph, pass, context);
 51	
 52	        // Execute the pass
 53	        ExecutePass(graph, pass, context);
 54	
 55	        previousPass = pass;
 56	    }
 57	
 58	    return true;
 59	}
