142	void RenderGraphExecutor::TransitionTexture(GPUContext* context, GPUTexture* texture, int32 textureIndex, GPUResourceState newState)
143	{
144	    if (!texture || !context)
145	        return;
146	
147	    // Get current state
148	    ResourceState* currentState = _textureStates.TryGet(textureIndex);
149	    GPUResourceState oldState = currentState ? currentState->State : GPUResourceState::Common;
150	
151	    // Skip if already in correct state
152	    if (oldState == newState)
153	        return;
154	
155	    // Perform transition
156	    context->SetResourceState(texture, oldState, newState);
157	
158	    // Update tracked state
159	    if (currentState)
160	    {
161	        currentState->State = newState;
162	    }
163	    else
164	    {
165	        _textureStates.Add(textureIndex, ResourceState(newState));
166	    }
167	}
