211	void RenderGraphExecutor::InsertSynchronization(GPUContext* context, RenderGraphPass* previousPass, RenderGraphPass* currentPass)
212	{
213	    if (!context || !previousPass || !currentPass)
214	        return;
215	
216	    // Check if passes can run in parallel
217	    bool canRunInParallel = false;
218	
219	    // Async compute: compute passes can overlap with raster passes
220	    if (_asyncComputeEnabled)
221	    {
222	        if (previousPass->IsRaster() && currentPass->IsCompute())
223	            canRunInParallel = true;
224	        else if (previousPass->IsCompute() && currentPass->IsRaster())
225	            canRunInParallel = true;
226	    }
227	
228	    // Async copy: copy passes can overlap with other passes
229	    if (_asyncCopyEnabled)
230	    {
231	        if (previousPass->IsCopy() || currentPass->IsCopy())
232	            canRunInParallel = true;
233	    }
234	
235	    // If passes cannot run in parallel, insert a barrier
236	    if (!canRunInParallel)
237	    {
238	        // Check for resource dependencies
239	        bool hasResourceDependency = false;
240	
241	        // Check if current pass reads what previous pass wrote
242	        for (int32 i = 0; i < currentPass->_textureReads.Count(); i++)
243	        {
244	            for (int32 j = 0; j < previousPass->_textureWrites.Count(); j++)
245	            {
246	                if (currentPass->_textureReads[i] == previousPass->_textureWrites[j])
247	                {
248	                    hasResourceDependency = true;
249	                    break;
250	                }
251	            }
252	            if (hasResourceDependency)
253	                break;
254	        }
255	
256	        if (!hasResourceDependency)
257	        {
258	            for (int32 i = 0; i < currentPass->_bufferReads.Count(); i++)
259	            {
260	                for (int32 j = 0; j < previousPass->_bufferWrites.Count(); j++)
261	                {
262	                    if (currentPass->_bufferReads[i] == previousPass->_bufferWrites[j])
263	                    {
264	                        hasResourceDependency = true;
265	                        break;
266	                    }
267	                }
268	                if (hasResourceDependency)
269	                    break;
270	            }
271	        }
272	
273	        // Insert barrier if there's a dependency
274	        if (hasResourceDependency)
275	        {
276	            context->FlushState();
277	        }
278	    }
279	}
