 64	bool GBufferPass::setupResources()
 65	{
 66	    if (!_gBufferShader || !_gBufferShader->IsLoaded())
 67	        return true;
 68	    auto gbuffer = _gBufferShader->GetShader();
 69	
 70	    // Validate shader constant buffers sizes
 71	    if (gbuffer->GetCB(0)->GetSize() != sizeof(GBufferPassData))
 72	    {
 73	        LOG(Warning, "GBuffer shader has incorrct constant buffers sizes.");
 74	        return true;
 75	    }
 76	
 77	    // Create pipeline stages
 78	    GPUPipelineState::Description psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
 79	    if (!_psDebug->IsValid())
 80	    {
 81	        psDesc.PS = gbuffer->GetPS("PS_DebugView");
 82	        if (_psDebug->Init(psDesc))
 83	            return true;
 84	    }
 85	    if (!_psLinearToSrgb->IsValid())
 86	    {
 87	        psDesc.PS = gbuffer->GetPS("PS_LinearToSrgb");
 88	        if (_psLinearToSrgb->Init(psDesc))
 89	            return true;
 90	    }
 91	
 92	    return false;
