155	void GBufferPass::Fill(RenderContext& renderContext, GPUTexture* lightBuffer)
156	{
157	    PROFILE_GPU_CPU("GBuffer");
158	
159	    // Cache data
160	    auto device = GPUDevice::Instance;
161	    auto context = device->GetMainContext();
162	    GPUTextureView* targetBuffers[5] =
163	    {
164	        lightBuffer->View(),
165	        renderContext.Buffers->GBuffer0->View(),
166	        renderContext.Buffers->GBuffer1->View(),
167	        renderContext.Buffers->GBuffer2->View(),
168	        renderContext.Buffers->GBuffer3->View(),
169	    };
170	    renderContext.View.Pass = DrawPass::GBuffer;
171	    context->SetViewportAndScissors(renderContext.Buffers->GetViewport());
172	
173	    // Clear GBuffer
174	    {
175	        PROFILE_GPU_CPU_NAMED("Clear");
176	
177	        context->ClearDepth(*renderContext.Buffers->DepthBuffer);
178	        context->Clear(lightBuffer->View(), Color::Transparent);
179	        context->Clear(renderContext.Buffers->GBuffer0->View(), Color::Transparent);
180	        context->Clear(renderContext.Buffers->GBuffer1->View(), Color::Transparent);
181	        context->Clear(renderContext.Buffers->GBuffer2->View(), Color(1, 0, 0, 0));
182	        context->Clear(renderContext.Buffers->GBuffer3->View(), Color::Transparent);
183	    }
184	
185	    // Ensure to have valid data
186	    if (checkIfSkipPass())
187	    {
188	        // Resources are missing. Do not perform rendering.
189	        return;
190	    }
191	
192	#if USE_EDITOR
193	    // Special debug drawing
194	    if (renderContext.View.Mode == ViewMode::MaterialComplexity)
195	    {
196	        // Initialize background with complexity of the sky (uniform)
197	        if (renderContext.List->Sky)
198	        {
199	            renderContext.List->Sky->ApplySky(context, renderContext, Matrix::Identity);
200	            GPUPipelineState* materialPs = context->GetState();
201	            const float complexity = (float)Math::Min(materialPs->Complexity, MATERIAL_COMPLEXITY_LIMIT) / MATERIAL_COMPLEXITY_LIMIT;
202	            context->Clear(lightBuffer->View(), Color(complexity, complexity, complexity, 1.0f));
203	            renderContext.List->Sky = nullptr;
204	        }
205	    }
206	    else if (renderContext.View.Mode == ViewMode::PhysicsColliders)
207	    {
208	        context->ResetRenderTarget();
209	        return;
210	    }
211	#endif
212	
213	    // Draw objects that can get decals
214	    context->SetRenderTarget(*renderContext.Buffers->DepthBuffer, ToSpan(targetBuffers, ARRAY_COUNT(targetBuffers)));
215	    renderContext.List->ExecuteDrawCalls(renderContext, DrawCallsListType::GBuffer);
216	
217	    // Draw decals
218	    DrawDecals(renderContext, lightBuffer->View());
219	
220	    // Draw objects that cannot get decals
221	    context->SetRenderTarget(*renderContext.Buffers->DepthBuffer, ToSpan(targetBuffers, ARRAY_COUNT(targetBuffers)));
222	    renderContext.List->ExecuteDrawCalls(renderContext, DrawCallsListType::GBufferNoDecals);
223	
224	    GPUTexture* nullTexture = nullptr;
225	    renderContext.List->RunCustomPostFxPass(context, renderContext, PostProcessEffectLocation::AfterGBufferPass, lightBuffer, nullTexture);
226	
227	    // Draw sky
228	    if (renderContext.List->Sky && _skyModel && _skyModel->CanBeRendered() && EnumHasAnyFlags(renderContext.View.Flags, ViewFlags::Sky))
229	    {
230	        PROFILE_GPU_CPU_NAMED("Sky");
231	        context->SetRenderTarget(*renderContext.Buffers->DepthBuffer, ToSpan(targetBuffers, ARRAY_COUNT(targetBuffers)));
232	        DrawSky(renderContext, context);
233	    }
234	
235	    context->ResetRenderTarget();
236	}
