 70	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 1, PerFrame);
 71	
 72	    // Create pipeline stages
 73	    GPUPipelineState::Description psDesc;
 74	    if (!_psLightDir.IsValid())
 75	    {
 76	        psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
 77	        psDesc.BlendMode = BlendingMode::Add;
 78	        psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::RGB;
 79	        psDesc.DepthWriteEnable = false;
 80	        psDesc.DepthEnable = psDesc.DepthBoundsEnable = _depthBounds;
 81	        if (_psLightDir.Create(psDesc, shader, "PS_Directional"))
 82	            return true;
 83	    }
 84	    if (!_psLightPoint.IsValid())
 85	    {
 86	        psDesc = GPUPipelineState::Description::DefaultNoDepth;
 87	        psDesc.BlendMode = BlendingMode::Add;
 88	        psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::RGB;
 89	        psDesc.VS = shader->GetVS("VS_Model");
 90	        psDesc.DepthEnable = true;
 91	        psDesc.DepthBoundsEnable = _depthBounds;
 92	        psDesc.CullMode = CullMode::Normal;
 93	        if (_psLightPoint.Create(psDesc, shader, "PS_Point"))
 94	            return true;
 95	        psDesc.DepthFunc = ComparisonFunc::Greater;
 96	        psDesc.CullMode = CullMode::Inverted;
 97	        if (_psLightPointInside.Create(psDesc, shader, "PS_Point"))
 98	            return true;
 99	    }
100	    if (!_psLightSpot.IsValid())
101	    {
102	        psDesc = GPUPipelineState::Description::DefaultNoDepth;
103	        psDesc.BlendMode = BlendingMode::Add;
104	        psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::RGB;
105	        psDesc.VS = shader->GetVS("VS_Model");
106	        psDesc.DepthEnable = true;
107	        psDesc.DepthBoundsEnable = _depthBounds;
108	        psDesc.CullMode = CullMode::Normal;
109	        if (_psLightSpot.Create(psDesc, shader, "PS_Spot"))
110	            return true;
111	        psDesc.DepthFunc = ComparisonFunc::Greater;
112	        psDesc.CullMode = CullMode::Inverted;
113	        if (_psLightSpotInside.Create(psDesc, shader, "PS_Spot"))
114	            return true;
115	    }
116	    if (!_psLightSky->IsValid())
117	    {
118	        psDesc = GPUPipelineState::Description::DefaultNoDepth;
119	        psDesc.BlendMode = BlendingMode::Add;
120	        psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::RGB;
121	        psDesc.VS = shader->GetVS("VS_Model");
122	        psDesc.PS = shader->GetPS("PS_Sky");
123	        psDesc.DepthEnable = true;
124	        psDesc.DepthBoundsEnable = _depthBounds;
125	        psDesc.CullMode = CullMode::Normal;
126	        if (_psLightSky->Init(psDesc))
127	            return true;
128	        psDesc.DepthFunc = ComparisonFunc::Greater;
129	        psDesc.CullMode = CullMode::Inverted;
130	        if (_psLightSkyInside->Init(psDesc))
131	            return true;
132	    }
133	
134	    return false;
135	}
